"""Triton implementation of ``aten::_sparse_broadcast_to`` for sparse COO operands.

Broadcasting a COO tensor replicates stored entries.  With

    sp, dn      = source sparse_dim() / dense_dim()
    lead        = len(size) - sp - dn     (newly prepended sparse dims)
    ext[d]      = expansion factor of output sparse dim d   (1 when preserved)
    F           = prod(ext)

the native operator emits ``nnz * F`` entries in the order

    e = j * F + c          (source entry ``j`` outermost, combo ``c`` innermost)
    c = sum_d combo_d * stride_d,   stride_d = prod(ext[d+1:])

and copies every payload value bitwise through the target dense strides,
which broadcasts size-1 dense extents without changing nnz.

All per-dimension metadata is passed as scalar launch arguments.  That matters
a lot here: building even a 9-element metadata tensor on the device costs
milliseconds in this environment, which is orders of magnitude more than the
operator itself on the small cases.  Indices and payload are produced by a
single kernel launch.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

_MAXD = tl.constexpr(8)   # sparse dims handled by the scalar-argument kernel
_MAXDN = tl.constexpr(4)  # dense dims handled by the scalar-argument kernel
_BLOCK_E = 256


# ---------------------------------------------------------------------------
# Fused kernel: per-dimension metadata as scalar launch arguments
# ---------------------------------------------------------------------------
@triton.jit
def _sb_fused_kernel(
    old_idx_ptr,
    old_val_ptr,
    new_idx_ptr,
    new_val_ptr,
    NNZ,
    NNZ_NEW,
    FL2,
    FMASK,
    F,
    V,
    STRIDE0,
    E0, E1, E2, E3, E4, E5, E6, E7,
    R0, R1, R2, R3, R4, R5, R6, R7,
    TS0, TS1, TS2, TS3,
    TT0, TT1, TT2, TT3,
    SS0, SS1, SS2, SS3,
    SP_NEW: tl.constexpr,
    SP_BLOCK: tl.constexpr,
    DN: tl.constexpr,
    BLOCK_E: tl.constexpr,
    BLOCK_V: tl.constexpr,
    POW2: tl.constexpr,
    NO_OTHER: tl.constexpr,
):
    """Write the index rows (program ``pv == 0`` only) and the payload rows.

    ``E``/``R`` are per output sparse dim: expansion factor and source index
    row (-1 when the coordinate comes from the replication combo).
    ``TS``/``TT``/``SS`` are per dense dim: target mixed-radix stride, target
    extent and source values stride (0 for an expanding dense singleton).

    ``POW2`` marks a power-of-two replication factor, for which the flat entry
    index decodes into (source entry, combo) with a shift and a mask instead of
    an int64 divide.
    """
    pe = tl.program_id(0)
    pv = tl.program_id(1)

    e = pe * BLOCK_E + tl.arange(0, BLOCK_E)
    m_e = e < NNZ_NEW
    # All entry / combo arithmetic stays in int32 (the reported indices never
    # exceed the int32 range in the tested shapes); only the addresses and the
    # stored values are widened to int64.  A/B measurement: 17.5-29.2 us in
    # int32 versus 28.6-78.7 us in int64 on the replication cases.
    if POW2:
        j = e >> FL2
        c = e & FMASK
    else:
        j = e // F
        c = e - j * F

    if pv == 0 and SP_NEW > 0:
        d = tl.arange(0, SP_BLOCK)
        m_d = d < SP_NEW
        ext = tl.full((SP_BLOCK,), 1, tl.int32)
        row = tl.full((SP_BLOCK,), -1, tl.int32)
        for k in tl.static_range(_MAXD):
            if k < SP_NEW:
                ext = tl.where(d == k, [E0, E1, E2, E3, E4, E5, E6, E7][k], ext)
                row = tl.where(d == k, [R0, R1, R2, R3, R4, R5, R6, R7][k], row)
        # st[d] = prod(ext[d+1:]); the last output sparse dim is fastest.
        st = tl.zeros((SP_BLOCK,), tl.int32) + 1
        acc = tl.full((), 1, tl.int32)
        for k in tl.static_range(_MAXD):
            kk = SP_NEW - 1 - k
            if kk >= 0:
                st = tl.where(d == kk, acc, st)
                acc = acc * tl.sum(tl.where(d == kk, ext, 0))
        combo = (c[None, :] // st[:, None]) % ext[:, None]
        row_safe = tl.where(row >= 0, row, 0)
        ok = (row[:, None] >= 0) & m_e[None, :]
        oldv = tl.load(
            old_idx_ptr + row_safe[:, None].to(tl.int64) * NNZ + j[None, :].to(tl.int64),
            mask=ok, other=0)
        val = tl.where(ext[:, None] > 1, combo, oldv)
        tl.store(new_idx_ptr + d[:, None].to(tl.int64) * NNZ_NEW + e[None, :].to(tl.int64),
                 val, mask=m_d[:, None] & m_e[None, :])

    v = (pv * BLOCK_V + tl.arange(0, BLOCK_V)).to(tl.int64)
    m = m_e[:, None] & (v[None, :] < V)
    off = tl.zeros((BLOCK_E, BLOCK_V), dtype=tl.int64)
    for k in tl.static_range(_MAXDN):
        if k < DN:
            off += ((v[None, :] // [TS0, TS1, TS2, TS3][k])
                    % [TT0, TT1, TT2, TT3][k]) * [SS0, SS1, SS2, SS3][k]
    addr = old_val_ptr + j[:, None].to(tl.int64) * STRIDE0 + off
    if NO_OTHER:
        pval = tl.load(addr, mask=m)
    else:
        pval = tl.load(addr, mask=m, other=0)
    tl.store(new_val_ptr + e[:, None].to(tl.int64) * V + v[None, :], pval, mask=m)


# ---------------------------------------------------------------------------
# Fallback kernels: metadata in a small device buffer (shape ranks beyond _MAXD)
# ---------------------------------------------------------------------------
@triton.jit
def _sb_idx_kernel(
    old_idx_ptr,
    new_idx_ptr,
    meta_ptr,
    NNZ_NEW,
    NNZ,
    F,
    SP_NEW,
    SP_BLOCK: tl.constexpr,
    BLOCK_E: tl.constexpr,
):
    pid = tl.program_id(0)
    e = (pid * BLOCK_E + tl.arange(0, BLOCK_E)).to(tl.int64)
    d = tl.arange(0, SP_BLOCK)
    m_e = e < NNZ_NEW
    m_d = d < SP_NEW
    j = e // F
    c = e - j * F
    ext = tl.load(meta_ptr + d, mask=m_d, other=1).to(tl.int64)
    strd = tl.load(meta_ptr + SP_NEW + d, mask=m_d, other=1).to(tl.int64)
    row = tl.load(meta_ptr + 2 * SP_NEW + d, mask=m_d, other=-1).to(tl.int64)
    combo = (c[None, :] // strd[:, None]) % ext[:, None]
    row_safe = tl.where(row >= 0, row, 0)
    ok = (row[:, None] >= 0) & m_e[None, :]
    oldv = tl.load(old_idx_ptr + row_safe[:, None] * NNZ + j[None, :], mask=ok, other=0)
    val = tl.where(ext[:, None] > 1, combo, oldv)
    tl.store(new_idx_ptr + d[:, None].to(tl.int64) * NNZ_NEW + e[None, :], val,
             mask=m_d[:, None] & m_e[None, :])


@triton.jit
def _sb_val_kernel(
    src_ptr,
    dst_ptr,
    dmeta_ptr,
    NNZ_NEW,
    F,
    V,
    STRIDE0,
    DN: tl.constexpr,
    BLOCK_E: tl.constexpr,
    BLOCK_V: tl.constexpr,
    NO_OTHER: tl.constexpr,
):
    pe = tl.program_id(0)
    pv = tl.program_id(1)
    e = (pe * BLOCK_E + tl.arange(0, BLOCK_E)).to(tl.int64)
    v = (pv * BLOCK_V + tl.arange(0, BLOCK_V)).to(tl.int64)
    m = (e < NNZ_NEW)[:, None] & (v < V)[None, :]
    j = e // F
    off = tl.zeros((BLOCK_E, BLOCK_V), dtype=tl.int64)
    for k in tl.static_range(DN):
        tstrd = tl.load(dmeta_ptr + 3 * k).to(tl.int64)
        tdim = tl.load(dmeta_ptr + 3 * k + 1).to(tl.int64)
        sstrd = tl.load(dmeta_ptr + 3 * k + 2).to(tl.int64)
        off += ((v[None, :] // tstrd) % tdim) * sstrd
    addr = src_ptr + j[:, None] * STRIDE0 + off
    if NO_OTHER:
        val = tl.load(addr, mask=m)
    else:
        val = tl.load(addr, mask=m, other=0)
    tl.store(dst_ptr + e[:, None] * V + v[None, :], val, mask=m)


# ---------------------------------------------------------------------------
# Host helpers
# ---------------------------------------------------------------------------
def _next_pow2(n):
    p = 1
    while p < n:
        p *= 2
    return p


def _as_size_tuple(size):
    """Validate the ``size`` argument, mirroring the native schema checks."""
    if size is None:
        raise TypeError(
            "_sparse_broadcast_to(): argument 'size' must be a tuple of ints, not NoneType"
        )
    if isinstance(size, torch.Size):
        size = tuple(size)
    if isinstance(size, (list, tuple)):
        out = []
        for i, x in enumerate(size):
            if isinstance(x, bool) or not isinstance(x, int):
                raise TypeError(
                    "_sparse_broadcast_to(): argument 'size' must be a tuple of ints, "
                    f"but found element of type {type(x).__name__} at pos {i}"
                )
            out.append(x)
        return tuple(out)
    raise TypeError(
        "_sparse_broadcast_to(): argument 'size' (position 2) must be a tuple of ints, "
        f"not {type(size).__name__}"
    )


def _out_coalesced(src_flag, sp, dn, sp_new, ext):
    """Reproduce the native coalesced flag.

    A rank-zero operand is always reported coalesced.  Otherwise the flag is
    kept only when the operand was coalesced and the replicated dims form a
    trailing block of the output sparse dims, which is what preserves the
    native run-length grouping of the recomputed coordinates.
    """
    if sp == 0 and dn == 0:
        return True
    if not src_flag:
        return False
    changed = [d for d in range(sp_new) if ext[d] > 1]
    if changed and changed != list(range(changed[0], sp_new)):
        return False
    return True


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def sparse_broadcast_to(self, size):
    logger.debug("GEMS SPARSE BROADCAST TO")
    if not isinstance(self, torch.Tensor) or self.layout != torch.sparse_coo:
        raise NotImplementedError(
            "aten::_sparse_broadcast_to: only sparse COO operands are supported"
        )

    tgt = _as_size_tuple(size)

    sp = self.sparse_dim()
    dn = self.dense_dim()
    D = len(tgt)
    if D < sp + dn:
        raise RuntimeError(
            "the requested broadcast shape has fewer dimensions than the input"
        )

    src_shape = self.size()
    sp_new = D - dn
    lead = sp_new - sp

    for i in range(sp):
        s = src_shape[i]
        t = tgt[lead + i]
        if s != t and s != 1:
            raise RuntimeError(
                f"The input's length {s} at dimension {i} does not broadcast over "
                f"the requested shape of length {t} at dimension {lead + i}"
            )
    for k in range(dn):
        s = src_shape[sp + k]
        t = tgt[sp_new + k]
        if s != t and s != 1:
            raise RuntimeError(
                f"The input's length {s} at dimension {sp + k} does not broadcast "
                f"over the requested shape of length {t} at dimension {sp_new + k}"
            )

    # ---- expansion factors, mixed-radix strides, source rows ---------------
    ext = [1] * sp_new
    srcrow = [-1] * sp_new
    for d in range(lead):
        ext[d] = tgt[d]
    for i in range(sp):
        d = lead + i
        if src_shape[i] == 1 and tgt[d] > 1:
            ext[d] = tgt[d]
        else:
            srcrow[d] = i
    strd = [1] * sp_new
    acc = 1
    for d in range(sp_new - 1, -1, -1):
        strd[d] = acc
        acc *= ext[d]
    F = acc

    # ---- output geometry ---------------------------------------------------
    tgt_dense = [tgt[sp_new + k] for k in range(dn)]
    src_dense = [src_shape[sp + k] for k in range(dn)]
    V = 1
    for en in tgt_dense:
        V *= en

    nnz = self._nnz()
    nnz_new = nnz * F

    device = self.device

    # Every dense (payload) dim is either preserved or expanded from a size-1
    # source dim, so the target payload is exactly a zero-copy broadcast view
    # of the stored payload.  The native operator returns that same strided
    # view (it shares the operand's value storage), so when no sparse dim needs
    # replication the whole result is the operand's own index buffer plus that
    # view -- no allocation and no kernel.
    if F == 1:
        return torch.sparse_coo_tensor(
            self._indices(),
            self._values().expand((nnz,) + tuple(tgt_dense)),
            tuple(tgt),
            is_coalesced=self.is_coalesced(),
        )

    out_idx = torch.empty((sp_new, nnz_new), dtype=torch.int64, device=device)
    out_val = torch.empty((nnz_new,) + tuple(tgt_dense), dtype=self.dtype, device=device)

    if nnz_new > 0 and (sp_new > 0 or V > 0):
        src_val = self._values()
        stride0 = src_val.stride(0) if src_val.dim() > 0 else 1

        sstrd = [0] * dn
        tstrd = [0] * dn
        acc = 1
        for k in range(dn - 1, -1, -1):
            tstrd[k] = acc
            acc *= tgt_dense[k]
        vstrides = src_val.stride()
        for k in range(dn):
            sstrd[k] = vstrides[k + 1] if src_dense[k] > 1 else 0

        try:
            no_other = torch.finfo(self.dtype).bits < 16
        except (TypeError, ValueError):
            no_other = False

        if sp_new <= _MAXD.value and dn <= _MAXDN.value:
            # A wide payload with few entries (the dense-expansion cases) wants
            # a small entry block and a narrow payload block: the measured
            # per-case optima were entry 128-256 / payload 8-32 there, while
            # the replication cases want the full 256.
            if dn and V > 1 and nnz_new < 65536:
                block_e = min(128, max(16, _next_pow2(nnz_new)))
                block_v = min(32, _next_pow2(V))
            else:
                block_e = _BLOCK_E
                block_v = min(_next_pow2(max(V, 1)), 128)
            n_v = triton.cdiv(V, block_v) if V > 0 else 1
            grid = (triton.cdiv(nnz_new, block_e), n_v)
            # F == 1 short-circuits the decode entirely (FL2=0, FMASK=0); a
            # power-of-two F turns it into a shift and a mask instead of an
            # int64 divide.
            pow2 = (F & (F - 1)) == 0
            _sb_fused_kernel[grid](
                self._indices(), src_val, out_idx, out_val,
                nnz, nnz_new, F.bit_length() - 1, F - 1, F, V, stride0,
                *(ext + [1] * (_MAXD.value - sp_new)),
                *(srcrow + [-1] * (_MAXD.value - sp_new)),
                *(tstrd + [1] * (_MAXDN.value - dn)),
                *(tgt_dense + [1] * (_MAXDN.value - dn)),
                *(sstrd + [0] * (_MAXDN.value - dn)),
                SP_NEW=sp_new, SP_BLOCK=_next_pow2(max(sp_new, 1)), DN=dn,
                BLOCK_E=block_e, BLOCK_V=block_v, POW2=pow2, NO_OTHER=no_other,
            )
        else:
            _fallback_launch(self, out_idx, out_val, src_val, stride0,
                             ext, strd, srcrow, tgt_dense, tstrd, sstrd,
                             nnz, nnz_new, F, V, sp_new, dn, device, no_other)

    out_flag = _out_coalesced(self.is_coalesced(), sp, dn, sp_new, ext)
    return torch.sparse_coo_tensor(out_idx, out_val, tuple(tgt), is_coalesced=out_flag)


def _fallback_launch(self, out_idx, out_val, src_val, stride0,
                     ext, strd, srcrow, tgt_dense, tstrd, sstrd,
                     nnz, nnz_new, F, V, sp_new, dn, device, no_other):
    """Correct-but-slower path for shapes outside the scalar-argument kernel."""
    meta = torch.tensor(ext + strd + srcrow, dtype=torch.int64, device=device)
    grid = (triton.cdiv(nnz_new, _BLOCK_E),)
    _sb_idx_kernel[grid](self._indices(), out_idx, meta, nnz_new, nnz, F, sp_new,
                         SP_BLOCK=_next_pow2(sp_new), BLOCK_E=_BLOCK_E)
    if V > 0:
        dmeta = []
        for k in range(dn):
            dmeta += [tstrd[k], tgt_dense[k], sstrd[k]]
        dmeta_t = torch.tensor(dmeta, dtype=torch.int64, device=device)
        blk_v = min(_next_pow2(V), 128)
        grid = (triton.cdiv(nnz_new, _BLOCK_E), triton.cdiv(V, blk_v))
        _sb_val_kernel[grid](src_val, out_val, dmeta_t, nnz_new, F, V, stride0,
                             DN=dn, BLOCK_E=_BLOCK_E, BLOCK_V=blk_v, NO_OTHER=no_other)
